### backend/game/skip_next_untap_step_target_test.go:1-69
package game

import "testing"

// TestSkipNextUntapStep_TargetDoesntUntapNextStep exercises the
// skip_next_untap_step primitive (ticket #3458, REPARSE-MAP
// static_unmapped) end-to-end through ExecuteAbilityEffect and the real
// untap step: a StackObject carrying the effect marks the targeted
// creature to skip its controller's next untap step, a SIBLING permanent
// controlled by the same player untaps normally that same step, and the
// mark is one-shot — a SECOND untap step untaps the target normally.
func TestSkipNextUntapStep_TargetDoesntUntapNextStep(t *testing.T) {
	gs := NewGame("P0", "P1", false)

	source := NewCreature("Skip Untap Test Caster", ManaCost{}, 1, 1, 1)
	source.Owner, source.Controller = 0, 0
	gs.Battlefield.AddCard(source)

	target := NewCreature("Skip Untap Test Target", ManaCost{}, 2, 2, 2)
	target.Owner, target.Controller = 1, 1
	target.Tapped = true
	gs.Battlefield.AddCard(target)

	sibling := NewCreature("Skip Untap Test Sibling", ManaCost{}, 2, 2, 2)
	sibling.Owner, sibling.Controller = 1, 1
	sibling.Tapped = true
	gs.Battlefield.AddCard(sibling)

	stackObj := &StackObject{
		IsAbility:   true,
		Text:        "skip_next_untap_step",
		Controller:  0,
		Card:        source,
		EffectValue: map[string]interface{}{},
		Targets:     []Target{{Type: TargetCreature, CardID: target.ID, IsCard: true}},
	}

	if err := gs.ExecuteAbilityEffect(stackObj); err != nil {
		t.Fatalf("ExecuteAbilityEffect: %v", err)
	}

	if !target.SkipNextUntap {
		t.Fatalf("expected target to be marked SkipNextUntap")
	}

	// Controller's next untap step: target stays tapped, sibling untaps normally.
	if err := ExecuteUntapStep(gs.Players[1], gs.Battlefield); err != nil {
		t.Fatalf("ExecuteUntapStep: %v", err)
	}

	if !target.Tapped {
		t.Fatalf("target should have stayed tapped through its skipped untap step")
	}
	if sibling.Tapped {
		t.Fatalf("sibling should have untapped normally")
	}
	if target.SkipNextUntap {
		t.Fatalf("SkipNextUntap should be one-shot and cleared after being consumed")
	}

	// A LATER untap step, with no new skip, must untap the target normally.
	target.Tapped = true
	if err := ExecuteUntapStep(gs.Players[1], gs.Battlefield); err != nil {
		t.Fatalf("ExecuteUntapStep (second): %v", err)
	}
	if target.Tapped {
		t.Fatalf("skip mark persisted into a later untap step")
	}
}

