func TestReferentDoesntUntapNextStep_SkipsControllersNextUntapStep(t *testing.T) {
	gs := NewGame("P0", "P1", false)

	source := NewCreature("Referent Untap Test Caster", ManaCost{}, 1, 1, 1)
	source.Owner, source.Controller = 0, 0
	gs.Battlefield.AddCard(source)

	target := NewCreature("Referent Untap Test Target", ManaCost{}, 2, 2, 2)
