	target.Tapped = true
	gs.Battlefield.AddCard(target)

	stackObj := &StackObject{
		IsAbility:   true,
		Text:        "referent_doesnt_untap_next_step",
		Controller:  0,
		Card:        source,
		EffectValue: map[string]interface{}{},
		Targets:     []Target{{Type: TargetCreature, CardID: target.ID, IsCard: true}},
	}

	if err := gs.ExecuteAbilityEffect(stackObj); err != nil {
		t.Fatalf("ExecuteAbilityEffect: %v", err)
	}

	if !target.SkipNextUntap {
		t.Fatalf("expected targeted creature to have SkipNextUntap set")
	}

	gs.Battlefield.UntapAll(target.Controller)
	if !target.Tapped {
		t.Fatalf("expected targeted creature to remain tapped through its controller's next untap step")
	}
	if target.SkipNextUntap {
		t.Fatalf("expected SkipNextUntap to be consumed by UntapAll")
	}

	gs.Battlefield.UntapAll(target.Controller)
	if target.Tapped {
		t.Fatalf("expected targeted creature to untap normally on the following untap step")
	}
}

