import "testing"

// TestFactoryNGFreezeUntilNextUntap exercises the tap_referent_doesnt_untap
// primitive (ticket engine.auto-freeze-until-next-untap-2a686b6439, Kashi-Tribe
// Warriors class): "tap that creature and it doesn't untap during its
// controller's next untap step." The paired atom taps the target AND marks it
// with Card.SkipNextUntap (the existing exert-mechanic flag), consumed
// one-shot by Zone.UntapAll during the controller's next untap step. A
// sibling permanent controlled by the same player untaps normally, and a
// LATER untap step (with no new mark) untaps the target normally too.
func TestFactoryNGFreezeUntilNextUntap(t *testing.T) {
	gs := NewGame("P0", "P1", false)

	source := NewCreature("Freeze Test Caster", ManaCost{}, 1, 1, 1)
	source.Owner, source.Controller = 0, 0
	gs.Battlefield.AddCard(source)

	target := NewCreature("Freeze Test Target", ManaCost{}, 2, 2, 2)
	target.Owner, target.Controller = 1, 1
	gs.Battlefield.AddCard(target)

	sibling := NewCreature("Freeze Test Sibling", ManaCost{}, 2, 2, 2)
	sibling.Owner, sibling.Controller = 1, 1
	sibling.Tapped = true
	gs.Battlefield.AddCard(sibling)

	stackObj := &StackObject{
		IsAbility:   true,
		Text:        "tap_referent_doesnt_untap",
		Controller:  0,
		Card:        source,
		EffectValue: map[string]interface{}{},
		Targets:     []Target{{Type: TargetCreature, CardID: target.ID, IsCard: true}},
	}

	if err := gs.ExecuteAbilityEffect(stackObj); err != nil {
		t.Fatalf("ExecuteAbilityEffect: %v", err)
	}

	if !target.Tapped {
		t.Fatalf("expected target to be tapped by tap_referent_doesnt_untap")
	}
	if !target.SkipNextUntap {
		t.Fatalf("expected target to be marked SkipNextUntap")
	}

	// Controller's next untap step: target stays tapped, sibling untaps normally.
	if err := ExecuteUntapStep(gs.Players[1], gs.Battlefield); err != nil {
		t.Fatalf("ExecuteUntapStep: %v", err)
	}

	if !target.Tapped {
		t.Fatalf("target should have stayed tapped through its frozen untap step")
	}
	if sibling.Tapped {
		t.Fatalf("sibling should have untapped normally")
	}
	if target.SkipNextUntap {
		t.Fatalf("SkipNextUntap should be one-shot and cleared after being consumed")
	}

	// A LATER untap step, with no new freeze, must untap the target normally.
	if err := ExecuteUntapStep(gs.Players[1], gs.Battlefield); err != nil {
		t.Fatalf("ExecuteUntapStep (second): %v", err)
	}
	if target.Tapped {
		t.Fatalf("freeze mark persisted into a later untap step")
	}
}
