package cards

// Vocabulary linter — step 3b of docs/paragraph-schema-v2.md.
//
// Fails the build when NEW vocabulary appears anywhere without registration:
//   1. every effect/trigger/additional/restriction string in the whole carddb
//   2. every Effect:/Trigger: literal a parser pattern can emit
// must be inside  registry ∪ alias tables ∪ grandfather.
// The grandfather file is frozen (2026-08-01) and only ever shrinks, so this
// is a ratchet: today green, any future coinage red until registered with an
// executor + shape test.

import (
	"os"
	"path/filepath"
	"regexp"
	"testing"
)

func lintAbility(t *testing.T, card string, ab *AbilityDSL) {
	t.Helper()
	if !EffectAllowed(ab.Effect) {
		t.Errorf("UNREGISTERED effect %q on %q — add to V2EffectRegistry (with executor+shape test), not to the grandfather list", ab.Effect, card)
	}
	for _, atom := range ab.Effects {
		if !EffectAllowed(atom.Effect) {
			t.Errorf("UNREGISTERED effect %q (v2 atom) on %q", atom.Effect, card)
		}
		if atom.Granted != nil {
			lintAbility(t, card, atom.Granted)
		}
	}
	if !TriggerAllowed(ab.Trigger) {
		t.Errorf("UNREGISTERED trigger %q on %q — extend v1TriggerAlias or V2TriggerEvents", ab.Trigger, card)
	}
	if ab.TriggerV2 != nil && !ab.TriggerV2.Raw && !V2TriggerEvents[ab.TriggerV2.Event] {
		t.Errorf("native v2 trigger with event %q outside V2TriggerEvents on %q", ab.TriggerV2.Event, card)
	}
	if ab.Cost != nil {
		if !AdditionalAllowed(ab.Cost.Additional) {
			t.Errorf("UNREGISTERED cost.additional %q on %q", ab.Cost.Additional, card)
		}
		if !RestrictionAllowed(ab.Cost.Restriction) {
			t.Errorf("UNREGISTERED cost.restriction %q on %q", ab.Cost.Restriction, card)
		}
		if ab.Cost.RestrictionV2 != "" && !V2CostRestrictions[ab.Cost.RestrictionV2] {
			t.Errorf("restriction_v2 %q outside V2CostRestrictions on %q", ab.Cost.RestrictionV2, card)
		}
	}
}

// 1. The whole carddb speaks only allowed vocabulary.
func TestVocabularyClosedOverCardDB(t *testing.T) {
	db := loadWholeDB(t)
	for name, def := range db.Cards {
		for i := range def.Abilities {
			lintAbility(t, name, &def.Abilities[i])
		}
		if def.BackFaceDef != nil {
			for i := range def.BackFaceDef.Abilities {
				lintAbility(t, name+" (back)", &def.BackFaceDef.Abilities[i])
			}
		}
	}
}

// 2. The parser patterns can only emit allowed vocabulary — catches coinage
// before any card record even lands in the DB.
func TestVocabularyClosedOverParserPatterns(t *testing.T) {
	effRx := regexp.MustCompile(`Effect:\s*"([^"]+)"`)
	trgRx := regexp.MustCompile(`Trigger:\s*"([^"]+)"`)
	files, err := filepath.Glob("patterns_*.go")
	if err != nil || len(files) == 0 {
		t.Fatalf("no patterns_*.go found: %v", err)
	}
	for _, f := range files {
		src, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		for _, m := range effRx.FindAllStringSubmatch(string(src), -1) {
			if !EffectAllowed(m[1]) {
				t.Errorf("%s emits UNREGISTERED effect %q — register it (executor+shape test) before adding the pattern", f, m[1])
			}
		}
		for _, m := range trgRx.FindAllStringSubmatch(string(src), -1) {
			if !TriggerAllowed(m[1]) {
				t.Errorf("%s emits UNREGISTERED trigger %q", f, m[1])
			}
		}
	}
}

// 3. Registry hygiene: every registered primitive must carry an executor
// reference and a shape test — a registry entry without wiring is exactly the
// silent gap this whole architecture exists to prevent.
func TestRegistryEntriesAreWired(t *testing.T) {
	for name, p := range V2EffectRegistry {
		if p.Executor == "" || p.ShapeTest == "" {
			t.Errorf("V2EffectRegistry[%q] missing executor (%q) or shape test (%q)", name, p.Executor, p.ShapeTest)
		}
	}
	for name, p := range V2AdditionalRegistry {
		if p.Executor == "" || p.ShapeTest == "" {
			t.Errorf("V2AdditionalRegistry[%q] missing executor (%q) or shape test (%q)", name, p.Executor, p.ShapeTest)
		}
	}
