import "testing"

// Coverage-honesty gate (phase.rs pattern: a test that asserts records stay
// red). Gap markers ("custom", "tiered") are registered vocabulary so the
// ratchet linter stays green, but a record carrying one is by definition not
// fully parsed — it must never ship in a playable status.
func TestGapMarkersNeverOnPlayableCards(t *testing.T) {
	gapMarkers := map[string]bool{"custom": true, "tiered": true}
	// Reach-guard: the markers must actually be registered — otherwise this
	// test could pass vacuously while the vocabulary linter is red.
	for m := range gapMarkers {
		if _, ok := V2EffectRegistry[m]; !ok {
			t.Fatalf("gap marker %q not in V2EffectRegistry — registry_gap_markers.go out of sync", m)
		}
	}

	var hasMarker func(ab *AbilityDSL) bool
	hasMarker = func(ab *AbilityDSL) bool {
		if gapMarkers[ab.Effect] {
			return true
		}
		for i := range ab.Effects {
			if gapMarkers[ab.Effects[i].Effect] {
				return true
			}
			if g := ab.Effects[i].Granted; g != nil && hasMarker(g) {
				return true
			}
		}
		return false
	}
	checkFace := func(name string, status CardStatus, abilities []AbilityDSL) int {
		found := 0
		for i := range abilities {
			if hasMarker(&abilities[i]) {
				found++
				if status != StatusNeedsReview && status != StatusUnsupported {
					t.Errorf("gap marker on %q with status %q — a record carrying custom/tiered is not fully parsed and must stay review/unsupported", name, status)
				}
			}
		}
		return found
	}

	db := loadWholeDB(t)
	seen := 0
	for name, def := range db.Cards {
		seen += checkFace(name, def.Status, def.Abilities)
		if def.BackFaceDef != nil {
			seen += checkFace(name+" (back)", def.Status, def.BackFaceDef.Abilities)
		}
	}
	if seen == 0 {
		t.Log("no gap-marker records in corpus — markers stay registered for future imports")
	}
}
