			}
			full := filepath.Join(root, p)
			if _, err := os.Stat(full); err == nil {
				continue
			}
			// tolerate references to files a worker is asked to CREATE
			if strings.Contains(p, "<") || strings.Contains(strings.ToLower(p), "example") {
				continue
			}
			dir := filepath.Dir(full)
			if _, err := os.Stat(dir); err == nil {
				continue // parent exists; file may be created by the task
			}
			t.Errorf("%s references non-existent path %q (parent dir missing too)", filepath.Base(f), p)
		}
	}
}
